# Self-authored gradient JPEG, decoded independently with Pillow for PNG oracle.
# No data from the game is embedded. The live disc supplies the replay fixture.
import base64, pathlib, subprocess, sys, os
root=pathlib.Path(sys.argv[3]);root.mkdir(parents=True,exist_ok=True)
jpeg=root/'fixture.jpg';png=root/'reference.png'
jpeg.write_bytes(base64.b64decode(''))
png.write_bytes(base64.b64decode(''))
command=[sys.argv[1],sys.argv[2],str(jpeg),str(png)]
subprocess.run(command,check=True)
negative=subprocess.run(command+['--negative'],capture_output=True,text=True)
if negative.returncode==0 or 'abs((int)pixels[k]-reference[k])<=3' not in negative.stderr:
    raise SystemExit('Negative image oracle failed to detect intentional pixel corruption')
print('PASS intentional JPEG reference corruption rejected')

env=dict(os.environ,GT4_FILM_NEGATIVE="1")
film_negative=subprocess.run(command,env=env,capture_output=True,text=True)
if film_negative.returncode==0 or "decoded.frame[1].parameters[0][3]==1" not in film_negative.stderr:
    raise SystemExit("Negative film oracle failed to detect intentional pose corruption")
print("PASS intentional film pose corruption rejected")
